// moonPhaseIndex(raw) returns 0-7 matching the arrays above
inline int moonPhaseIndex(const String& raw) {
    if (raw == "NEW_MOON") return 0;
    if (raw == "WAXING_CRESCENT") return 1;
    if (raw == "FIRST_QUARTER") return 2;
    if (raw == "WAXING_GIBBOUS") return 3;
    if (raw == "FULL_MOON") return 4;
    if (raw == "WANING_GIBBOUS") return 5;
    if (raw == "LAST_QUARTER") return 6;
    if (raw == "WANING_CRESCENT") return 7;
    return 0;  // default to new moon
}

